create.endpoint:
POST /api/alerts
Body: { patient_id, appointment_id, message, alert_date, alert_time, repeat_count, repeat_interval }
Response: { success: true, alert_id, message }

update.endpoint:
PUT /api/alerts/{id}
Body: { message, alert_date, alert_time, repeat_count, repeat_interval, is_active, is_dismissed }
Response: { success: true, message }

create.endpoint:
POST /api/notes
Body: { title, content, x, y, width, height, color }
Response: { success: true, note: {...} }

update.endpoint:
PUT /api/notes/{id}
Body: { title?, content?, x?, y?, width?, height?, color? }
Response: { success: true, note: {...} }

change_password.endpoint:
POST /doctor/profile/change-password
Body: { new_password, confirm_password }
Response: Redirects to /doctor/profile?success=... or ?error=...

update_field.endpoint:
POST /doctor/profile/update-field
Body: { field, value }
Response: { success: true/false, message }

upload_file.endpoint:
POST /api/patients/files/upload
Body: FormData with patient_id, file, file_type, description
Response: { success: true, file_id, message }

capture_image.endpoint:
POST /api/patients/files/capture
Body: FormData with patient_id, image (base64 or blob), description
Response: { success: true, file_id, message }
